import{_ as r,o as i,c as o,ag as a}from"./chunks/framework.ePeAWSvT.js";const h=JSON.parse('{"title":"ADR-0004: 记忆职责边界 — 框架管确定性机制，应用管需要模型的判断","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0004-memory-boundary.md","filePath":"adr/0004-memory-boundary.md"}'),t={name:"adr/0004-memory-boundary.md"};function l(n,e,m,s,u,c){return i(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0004-记忆职责边界-—-框架管确定性机制-应用管需要模型的判断" tabindex="-1">ADR-0004: 记忆职责边界 — 框架管确定性机制，应用管需要模型的判断 <a class="header-anchor" href="#adr-0004-记忆职责边界-—-框架管确定性机制-应用管需要模型的判断" aria-label="Permalink to &quot;ADR-0004: 记忆职责边界 — 框架管确定性机制，应用管需要模型的判断&quot;">​</a></h1><ul><li><strong>状态</strong>：Proposed（2026-07-21，随 PR 评审定稿）</li><li><strong>日期</strong>：2026-07-21</li><li><strong>关联</strong>：<a href="./0001-llm-mode-memory.html">ADR-0001</a>（硬约束来源）、<a href="./0003-memu-cli-integration.html">ADR-0003</a>、<a href="https://github.com/XnneHangLab/wikimem/pull/14" target="_blank" rel="noreferrer">wikimem ADR 0001–0004</a>（框架侧对应决策：日记原语、时间检索、向量缓存元数据、接口契约）</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>wikimem 独立成库并即将新增日记原语与时间门控检索（见 wikimem <a href="https://github.com/XnneHangLab/wikimem/pull/14" target="_blank" rel="noreferrer">PR #14</a> 的 ADR-0001/0002）。随之浮现一批归属问题：时间意图识别放哪？日记由谁写、按什么策略写？情绪算不算记忆？记忆可视化落在哪个前端、走谁的接口？</p><p><a href="./0001-llm-mode-memory.html">ADR-0001</a> 的硬约束其实已经画了分界线的雏形：&quot;retrieve 0 次 LLM 调用；memorize 至多 1 次、异步、由宿主发起&quot;。本 ADR 把这条线推广成总原则，并逐项裁定归属。</p><p><strong>总原则</strong>：框架只做确定性的机制（规则、数学、IO）；任何需要模型判断的事都在应用侧。embedding 是唯一例外，且必须以&quot;可插拔、可缺席、失败即降级&quot;的方式注入。</p><p>一句话记法：<strong>正则是框架的地板，LLM 是应用的天花板，中间不存在第三个解析器。</strong></p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><h3 id="_1-时间意图识别-应用侧-tool-call" tabindex="-1">1. 时间意图识别 = 应用侧 tool call <a class="header-anchor" href="#_1-时间意图识别-应用侧-tool-call" aria-label="Permalink to &quot;1. 时间意图识别 = 应用侧 tool call&quot;">​</a></h3><ul><li>可枚举的时间表达（昨天/前天/上周X/X天前/X月X号）由 wikimem 的正则快通道兜底（wikimem ADR-0002），<strong>应用不重复实现</strong>。</li><li>模糊指称（&quot;上次我们吵架那天&quot;&quot;很久以前&quot;）由 LLM 在对话轮内以 tool call 产出结构化 <code>time_range</code>，传给 <code>retrieve(query, time_range=...)</code>。</li><li>事件锚定的两跳查询（先检索事件拿到日期，再围绕它开窗）由 tool 编排完成——这是只有应用侧能做的事。</li><li>两条来路汇合于 retrieve 的同一个参数，无并行链路。</li></ul><h3 id="_2-diary-writing-从-skill-prompt-升格为正式-memorize-策略" tabindex="-1">2. diary_writing 从 skill prompt 升格为正式 memorize 策略 <a class="header-anchor" href="#_2-diary-writing-从-skill-prompt-升格为正式-memorize-策略" aria-label="Permalink to &quot;2. diary_writing 从 skill prompt 升格为正式 memorize 策略&quot;">​</a></h3><ul><li>何时写、写什么、什么文风，归 prompt 与角色配置（<code>prompts/skills/diary_writing</code> 升格，per-character 开关进 <code>profiles/*.toml</code>）。</li><li><strong>硬约束不破</strong>：每轮仍至多 1 次异步 LLM 调用——单次抽取调用以结构化输出同时产出 (a) wiki 条目（现有 extraction）与 (b) 日记段落（生动短段落：场景、情绪、事实在一起），一次带回分别写入。</li><li>解析失败 fail-open：丢弃本轮 memorize，journal 留痕，不重试不阻塞。</li></ul><h3 id="_3-情绪状态留在应用运行时" tabindex="-1">3. 情绪状态留在应用运行时 <a class="header-anchor" href="#_3-情绪状态留在应用运行时" aria-label="Permalink to &quot;3. 情绪状态留在应用运行时&quot;">​</a></h3><ul><li>效价/唤醒度这类每轮变化的 runtime 状态（参照 MoeChat 的 emotion_state）<strong>不是记忆</strong>：不进 wikimem、不被检索，由应用插件持有与持久化。</li><li>事件中的情绪以日记文本的形式进入记忆（经第 2 条的日记段落）。</li><li>记法：<strong>状态即时，情绪入事。</strong></li></ul><h3 id="_4-记忆可视化放-launcher-tauri-每后端一个独立面板-走应用自身路由" tabindex="-1">4. 记忆可视化放 Launcher（Tauri）：每后端一个独立面板，走应用自身路由 <a class="header-anchor" href="#_4-记忆可视化放-launcher-tauri-每后端一个独立面板-走应用自身路由" aria-label="Permalink to &quot;4. 记忆可视化放 Launcher（Tauri）：每后端一个独立面板，走应用自身路由&quot;">​</a></h3><ul><li><strong>在 Launcher（Tauri）</strong>，与 <code>CharacterStatusPanel</code> 同构：Launcher 调用应用自己的 FastAPI 路由（<code>127.0.0.1:12393</code>）拿数据，提供翻阅、按时间检索、按内容搜索。翻阅式记忆可视化整体归 Launcher——它本就承载角色状态、profile、插件、console 等重面板，记忆面板与之为邻。</li><li><strong>Electron 前端只承载轻量运行时状态</strong>：对话中实时展示的少量状态随聊天窗走（如本轮是否写入记忆、命中回显）；完整记忆可视化不进前端，前端保持在聊天关键路径上的轻量。</li><li><strong>每个记忆后端一个独立面板，不合并</strong>：记忆后端以插件形式存在（<code>wikimem</code> 插件；memU 为 ADR-0003 的第二后端），面板<strong>随插件走、各自独立</strong>——wikimem 一个、memU 一个，不揉进同一个统一面板。两套后端形态差异大（wikimem 是 markdown + wiki-link + BM25，memU 另有一套模型与存储），合成一个面板会让取数、渲染、状态互相纠缠，代码难读、易混、越加越复杂；拆开各自简单，日后加第三个后端也只是再加一个面板。</li><li><strong>数据路径 per 后端，均不依赖 wikimem serve</strong>：wikimem 进程内 import（毫秒级），memU 经 memu-cli 子进程（2.1–2.4 s/call），但都走应用自己的 FastAPI 路由；serve 面向进程外第三方消费者（wikimem ADR-0004），不是宿主链路的一环。</li><li><strong>每个面板都是一等产品面，不是 demo</strong>：尤其自研的 wikimem，可视化要做得精致（时间线、wiki-link 关系、命中高亮这类），不是&quot;能跑就行&quot;的占位。</li><li>UI 长什么样百分之百归应用；框架只保证数据可及。</li></ul><h3 id="_5-现状追认" tabindex="-1">5. 现状追认 <a class="header-anchor" href="#_5-现状追认" aria-label="Permalink to &quot;5. 现状追认&quot;">​</a></h3><p>extraction prompt、user_id、token 预算等策略参数继续留在插件侧（<code>src/lab/plugins/wikimem</code>），不下沉到框架。</p><h2 id="理由" tabindex="-1">理由 <a class="header-anchor" href="#理由" aria-label="Permalink to &quot;理由&quot;">​</a></h2><ul><li>一条原则切完所有归属问题，与 ADR-0001 的硬约束同源，没有新增心智模型。</li><li>框架保持零 LLM、零策略，可独立发布独立测试；应用换模型、换 prompt、调策略都不动框架。</li><li>放弃的备选： <ul><li><strong>意图识别下沉进框架</strong>——框架就得持有 LLM 配置与调用链路，零依赖与&quot;retrieve 0 LLM&quot;双双破产；</li><li><strong>日记独立一次 LLM 调用</strong>——每轮 2 次调用，违反 ADR-0001 硬约束 2；</li><li><strong>情绪状态进记忆框架</strong>——每轮变化的状态会把 append-only 的事件流污染成高频可变存储，两头不像；</li><li><strong>记忆可视化塞进 Electron 前端</strong>——前端是实时聊天面，塞进可翻阅/可搜索的重面板会拖累关键路径；Launcher 已有 <code>CharacterStatusPanel</code> 等同类重面板，记忆面板与之为邻更自然；</li><li><strong>多后端合成一个统一面板</strong>——wikimem 与 memU 形态差异大，合一个面板会把两套取数/渲染/状态纠缠在一处，代码难读、易混、越加越复杂；改为每后端一个独立面板，随插件生长（同时也不写死单一后端）；</li><li><strong>前端走 wikimem serve</strong>——宿主进程内已有 API，多一跳 HTTP 纯属绕路。</li></ul></li></ul><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><p><strong>正面</strong></p><ul><li>wikimem 与应用的接缝收敛为：<code>retrieve(query, time_range)</code> 一个调用 + memorize 时的两类写入（wiki 条目 / 日记段落）。</li><li>时间检索的正则部分零成本常开（快通道），LLM 成本只在模型判断需要时发生（tool call 按需触发）。</li><li>记忆面板按后端拆分，各面板互不耦合、可独立演进，代码可读性优于统一面板；加后端 = 加面板，不动既有面板。</li></ul><p><strong>负面 / 代价</strong></p><ul><li>单次调用同时产出 wiki 条目 + 日记段落，结构化输出更复杂，解析失败面变大（以 fail-open + journal 留痕兜底）。</li><li>tool call 形态的意图识别依赖模型的工具调用质量，弱模型下&quot;该开窗没开窗&quot;会退化为普通语义检索（可接受：答不出 ≠ 答错）。</li><li>每个记忆后端一个独立面板，面板数量随后端增长；各自与自己后端的 API 有薄适配层，需随各自版本同步维护。共性 UI（时间线、搜索框、命中高亮）会在面板间重复，需抽公共组件避免各写各的；叠加&quot;精致而非 demo&quot;的产品级要求，总工作量高于一次性可视化。</li></ul><p><strong>实施</strong></p><p>依赖 wikimem ADR-0001/0002 落地后：插件侧改造（extraction 结构化输出扩展、time_range tool 注册）→ 各后端各自的 FastAPI 可视化路由 → Launcher 每后端一个独立面板（仿 <code>CharacterStatusPanel</code>，产品级 UI）→ per-character 配置项。各挂独立 issue。</p>',27)])])}const g=r(t,[["render",l]]);export{h as __pageData,g as default};
